      "name": "Experiments",
      "topics": [
        {
          "id": "experiment-1-introduction-to-engineering-graphics-principles",
          "name": "Introduction to Engineering Graphics: Principles of engineering graphics and their significance, drawing instruments & accessories, lettering and numbering, types of lines, dimensioning methods, basic geometric drawing, reading a drawing. st rd",
          "number": 1
        },
        {
          "id": "experiment-2-orthographic-projection-introduction-to-project",
          "name": "Orthographic Projection: Introduction to projection, types of projection, 1angle and 3angle projection",
          "number": 2,
          "requires": ["experiment-1-introduction-to-engineering-graphics-principles"]
        },
        {
          "id": "experiment-3-isometric-projection-principles-of-isometric-pr",
          "name": "Isometric Projection: Principles of isometric projection – isometric scale, isometric views, conventions, conversion of isometric views to orthographic views and vice-versa",
          "number": 3,
          "requires": ["experiment-2-orthographic-projection-introduction-to-project"]
