          "requires": ["experiment-4-projection-of-solids-and-development-of-surface"]
        },
        {
          "id": "experiment-6-basic-sketching-using-cad-tool-sketch-entities",
          "name": "Basic sketching using CAD tool: Sketch entities using tools – origin, points, lines, circle, arcs, polygons, fillets and chamfer, trim, extend and offset, copy, cut, delete and others",
          "number": 6,
          "requires": ["experiment-5-introduction-of-computer-aided-engineering-draw"]
        },
        {
          "id": "experiment-7-advanced-sketching-using-cad-tool-sketching-ent",
          "name": "Advanced sketching using CAD tool: Sketching entities using relation constrains, Mirror, Patterning, full definition of drawing and others",
          "number": 7,
          "requires": ["experiment-6-basic-sketching-using-cad-tool-sketch-entities"]
        },
        {
          "id": "experiment-8-basic-3d-modelling-using-cad-tool-extrude-cut-d",
          "name": "Basic 3D modelling using CAD tool: Extrude, cut, drawing on different planes, editing, symmetric, revolving, and others",
          "number": 8,
          "requires": ["experiment-7-advanced-sketching-using-cad-tool-sketching-ent"]
        },
        {
          "id": "experiment-9-computer-aided-drawing-sheets-preparing-drawing",
